95	    private Integer possibleDuplicateOf;
96	
97	    public Integer getPossibleDuplicateOf() { return this.possibleDuplicateOf; }
98	
99	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) { this.possibleDuplicateOf = possibleDuplicateOf; }
100	
101	    public boolean isPossibleDuplicate() { return this.possibleDuplicateOf != null; }
102	
